DO $$ BEGIN COMMENT ON TABLE public.tracking_unit IS 'A "watchlist" / tracking unit — one row per named search target an organization is monitoring (e.g. a brand, campaign, or topic). Carries the lifecycle window (tracking_unit_start_date/stop_date), market scope (tracking_unit_market_name, market_id), advertising context (advertiser_id, brand_id, campaign_id, buy_id, offer_id, broadcaster_*_id, creative_id), and tracking_unit_type (enum tracking / bias / etc.). The track_all/include_no_match booleans control match-aggregation behavior. Used by Search and Folder layers to scope mention queries.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.tracking_unit_market IS 'Schema-defined entity public.tracking_unit_market. Purpose to be verified against migration history.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
