DO $$ BEGIN COMMENT ON TABLE public.tree_folder IS 'Folder-flavor row inside the V1 tree-object system. Three columns: tree_folder_id (uuid PK), tree_folder_name, optional tree_folder_description. Pairs with tree_object via tree_object.object_id = tree_folder_id::text (when the tree-object''s type is "folder"). Carries the human-readable folder metadata that tree_object doesn''t store directly.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.tree_object IS 'Generic hierarchical-object node used by the folder system. Each row is one tree node (folder or content item): tree_object_id (uuid) is the surrogate key; object_id (text) links to the underlying entity (uuid or int4 depending on source PK — see existing column comment); tree_object_type_id discriminates node kind; tree_object_status is lifecycle; shared_with (jsonb) carries denormalized ACL hints. Parent/child relationships live in tree_object_closure.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.tree_object_closure IS 'Transitive closure of tree_object parent→child relationships. One row per (parent_tree_object_id, child_tree_object_id, depth), including self-edges at depth 0. Lets folder-membership and ancestor queries resolve in a single join rather than recursive CTEs. Maintained by dalFolder.js on every move/insert.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.tree_object_content_template IS 'Binds a tree_object (folder / SDO container) to a content-template SDO definition. One row per (tree_object_id, sdo_id, data_registry_id): defines which schema (data_registry_id) the contained content conforms to. deleted_date is the soft-delete marker (NULL = live). Used by the SDO-aware folder system to validate items added to a folder and to enumerate folders authoring a given schema.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.tree_object_status IS 'Lookup table enumerating tree_object statuses.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.tree_object_type IS 'Lookup table mapping tree_object_type ids to canonical type values.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.trending_topic IS 'Schema-defined entity public.trending_topic. Purpose to be verified against migration history.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
