DO $$ BEGIN COMMENT ON TABLE public.v2_folder_root IS 'Per-(organization, user, application) mapping of a folder to a root-folder anchor in the V2 folder system. Each row designates a v2_folder.folder_id as the root for a specific scope (organization-wide via organization_id, optionally further scoped by root_folder_user_id or root_folder_application_id). Replaces the V1 root_folder table for new code paths; resolves "where is this user''s home folder?" lookups. References public.v2_folder(folder_id).'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.v2_folder_sdo IS 'Binds an SDO (structured data object) to a v2_folder. Each row: folder_id (FK → v2_folder.folder_id), content_template_schema_id (uuid — the SDO schema, with existing column COMMENT: "Structured data schema id which sdo_data is compliant to"), sdo_id (text — existing column COMMENT: "the id of structured data object of type content_templte_schema_id"), plus created_by/modified_by/date_created/date_modified metrics. Replaces the V1 tree_object→sdo binding for new code paths.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
DO $$ BEGIN COMMENT ON TABLE public.v2_folder_treeobject IS 'Compatibility table mapping V2 folder ids back to their legacy V1 tree_object_id values. Per the migration header, this exists to support external stores that still reference the V1 tree-object ids until they migrate to the V2 model. PK = (folder_id, tree_object_id); CASCADE-deleted when v2_folder rows are removed. Read by the V2 folder DAL when resolving cross-model references; written by the OLP/migration topic eventing handlers.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
